<template>
  <div class="card">
    <div class="card-image img-container" :style="dataUrl ? 'background-image: url(' + dataUrl + ')' : ''">
      <!-- a format the browser cannot show (HEIC in Chrome and Firefox): the server converts it -->
      <fa-icon v-if="!dataUrl && !isInitial" icon="image" size="3x" class="no-preview" />
      <div class="action-buttons">
        <delete-button @click="$emit('delete-image')" :title="$gettext('Delete image')" />
        <rotate-button
          @click="applyRotation(90)"
          :disabled="rotateClicked || disabled"
          :title="$gettext('Rotate image right')"
          v-if="canRotate"
        />
        <rotate-button
          direction="left"
          @click="applyRotation(-90)"
          :disabled="rotateClicked || disabled"
          :title="$gettext('Rotate image left')"
          v-if="canRotate"
        />
      </div>
      <progress
        v-if="isSaving || isFailed"
        class="progress is-large"
        :class="{
          'is-success': isSuccess,
          'is-warning': isSaving,
          'is-danger': isFailed,
        }"
        :value="percentCompleted"
        max="100"
      >
        {{ percentCompleted }}%
      </progress>
    </div>

    <div
      class="card-content"
      :class="{ 'is-categories': categoriesEdition && !isFailed, 'is-same-photo': samePhoto && !isFailed }"
    >
      <!-- a photo the page already has: often sent again to give it another title -->
      <div v-if="!isFailed && samePhoto && samePhoto.choice === null" class="same-photo">
        <p>
          <strong v-translate>This photo is already on this page</strong>
          <br />
          <em v-if="samePhoto.title">{{ samePhoto.title }}</em>
          <em v-else class="has-text-grey" v-translate>untitled</em>
        </p>
        <p v-if="samePhoto.loadFailed" class="is-size-7 has-text-grey" v-translate>
          Couldn't check whether you can change its title.
        </p>
        <p v-else-if="samePhoto.editable === false" class="is-size-7 has-text-grey" v-translate>
          Only its author or a moderator can change its title.
        </p>
        <div class="buttons is-centered">
          <button
            v-if="samePhoto.loadFailed"
            class="button is-small is-primary"
            @click="$emit('reload-same-photo')"
            v-translate
          >
            Try again
          </button>
          <button
            v-else-if="samePhoto.editable !== false"
            class="button is-small is-primary"
            :class="{ 'is-loading': samePhoto.editable === null }"
            @click="$emit('choose', 'retitle')"
            v-translate
          >
            Change its title
          </button>
          <button class="button is-small" @click="$emit('choose', 'add')" v-translate>Add a copy</button>
        </div>
      </div>

      <div v-else-if="!isFailed && samePhoto && samePhoto.choice === 'retitle' && !categoriesEdition">
        <p class="same-photo-label is-size-7">
          <span v-translate>New title of the photo already on this page</span>
          ·
          <a @click="$emit('choose', null)" v-translate>Cancel</a>
        </p>
        <p v-if="samePhoto.loadFailed" class="same-photo-label is-size-7 has-text-danger">
          <span v-translate>Couldn't load this photo</span>
          ·
          <a @click="$emit('reload-same-photo')" v-translate>Try again</a>
        </p>
        <div class="field title-input">
          <div class="control">
            <input
              type="text"
              :placeholder="$gettext('title')"
              v-model="document.locales[0].title"
              maxlength="150"
              ref="retitleInput"
            />
          </div>
        </div>
      </div>

      <div v-else-if="!isFailed && samePhoto && samePhoto.choice === 'retitle'" class="same-photo">
        <p class="is-size-7 has-text-grey" v-translate>Only the title of this photo changes.</p>
        <p v-if="samePhoto.loadFailed" class="is-size-7 has-text-danger">
          <span v-translate>Couldn't load this photo</span>
          ·
          <a @click="$emit('reload-same-photo')" v-translate>Try again</a>
        </p>
      </div>

      <div v-else-if="!isFailed">
        <p v-if="samePhoto && samePhoto.choice === 'add'" class="same-photo-label is-size-7">
          <span v-translate>Copy of a photo already on this page</span>
          ·
          <a @click="$emit('choose', null)" v-translate>Cancel</a>
        </p>
        <div v-if="categoriesEdition" class="category-select">
          <label v-for="item of imageCategories" :key="item" class="checkbox">
            <input type="checkbox" :checked="document.categories.includes(item)" @input="toggleCategory(item)" />
            {{ $filters.uppercaseFirstLetter($gettext(item, 'image_categories')) }}
          </label>
        </div>

        <div v-else>
          <div class="field title-input">
            <div class="control">
              <input type="text" :placeholder="$gettext('title')" v-model="document.locales[0].title" maxlength="150" />
            </div>
          </div>

          <div class="columns is-mobile is-gapless licence-select">
            <div
              v-for="[licence, label] in Array.from(licences)"
              class="column has-text-centered"
              :class="{
                'has-background-success': document.image_type == licence,
                'is-4': licences.size === 3,
                'is-6': licences.size === 2,
              }"
              :key="licence"
              @click="document.image_type = licence"
            >
              <label>{{ $filters.uppercaseFirstLetter(label) }}</label>
            </div>
          </div>
        </div>
      </div>

      <div v-else class="buttons is-centered buttons-if-failed">
        <button @click="$emit('retry-upload')" class="button is-primary" v-translate>Retry</button>
        <button @click="$emit('delete-image')" class="button is-danger" v-translate>Cancel</button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
// https://github.com/c2corg/v6_ui/blob/master/c2corg_ui/static/js/imageuploader.js
import { computed, nextTick, ref, useTemplateRef, watch, type PropType } from 'vue';

import RotateButton from './RotateButton.vue';

import { useGlobalProperties } from '@/js/composables/global-properties';
import constants from '@/js/constants';

const props = defineProps({
  categoriesEdition: {
    type: Boolean,
    required: true,
  },
  dataUrl: {
    type: String,
    default: null,
  },
  status: {
    type: String,
    required: true,
  },
  percentCompleted: {
    type: Number,
    required: true,
  },
  document: {
    type: Object,
    required: true,
  },
  isInitial: {
    type: Boolean,
    required: true,
  },
  isSaving: {
    type: Boolean,
    required: true,
  },
  isSuccess: {
    type: Boolean,
    required: true,
  },
  isFailed: {
    type: Boolean,
    required: true,
  },
  canRotate: {
    type: Boolean,
    default: false,
  },
  // the photo of the page this one is a copy of, and what the user chose to do (ImagesUploader)
  samePhoto: {
    type: Object as PropType<{
      title: string;
      editable: boolean | null;
      loadFailed: boolean;
      choice: 'retitle' | 'add' | null;
    } | null>,
    default: null,
  },
});

const emit = defineEmits(['delete-image', 'retry-upload', 'rotate-image', 'choose', 'reload-same-photo']);

const { $gettext, $user } = useGlobalProperties();

const licences = new Map([
  ['collaborative', $gettext('collab')],
  ['personal', $gettext('personal')],
]);
if ($user.isModerator) {
  licences.set('copyright', $gettext('copyright'));
}

const rotate = ref(0);
const rotateClicked = ref(false);

const imageCategories = constants.objectDefinitions.image.fields.categories.values as string[];
const disabled = computed(() => props.isSaving || props.isFailed);

watch([() => props.isSaving, () => props.isFailed], () => {
  rotateClicked.value = false;
});

// the title field gets the focus once the user chose to change the title
const retitleInput = useTemplateRef<HTMLInputElement>('retitleInput');
watch(
  () => props.samePhoto?.choice,
  (choice) => {
    if (choice === 'retitle') {
      nextTick(() => retitleInput.value?.select());
    }
  }
);

function toggleCategory(category: string) {
  const newValue = props.document.categories.slice(0);

  if (!newValue.includes(category)) {
    newValue.push(category);
  } else {
    newValue.splice(newValue.indexOf(category), 1);
  }

  // the document of the upload, shared with ImagesUploader: changed in place

  props.document.categories = newValue;
}

function applyRotation(angle: number) {
  if (rotateClicked.value || disabled.value) {
    return;
  }
  rotateClicked.value = true;
  rotate.value = (rotate.value + angle) % 360;
  if (rotate.value < 0) {
    rotate.value += 360;
  }
  emit('rotate-image', rotate.value);
}
</script>

